_src.onWin:
async G => {
          G.addBadge('raio');
          await G.say('{N} recebeu a INSÍGNIA RAIO!', null, 'badge');
          await G.say('E leve estes orbes que eu mesmo aperfeiçoei!', 'Tião');
          G.giveItem('superorbe', 5);
          await G.say('{N} recebeu 5 SUPER ORBES!');
        }
